```cpp
#include <iostream>
#include <string>
#include <vector>

using namespace std;

// Recursive function to generate the Fibonacci sequence
vector<int> generateFibonacciSequence(int first, int second, int numElements) {
    if (numElements == 0) {
        return vector<int>();
    }

    vector<int> sequence = {first, second};
    for (int i = 2; i <= numElements; i++) {
        sequence.push_back(sequence[i - 1] + sequence[i - 2]);
    }

    return sequence;
}

