        cout << "Invalid input. Please enter two non-negative integers: ";
        cin.clear();
        cin.ignore(1000, '\n');
        cin >> first >> second;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    while (cin.fail() || numElements < 0) {
        cout << "Invalid input. Please enter a non-negative integer: ";
        cin.clear();
        cin.ignore(1000, '\n');
        cin >> numElements;
    }
}

int main() {
    int first, second, numElements;

    getInput(first, second, numElements);

    vector<int> sequence = generateFibonacciSequence(first, second, numElements);

    cout << "Generated sequence: ";
    for (int i = 0; i < sequence.size(); i++) {
