<?php

function format_order($order) {
    $formatted_order = [];

    // Loop through order items
    foreach ($order->get_items() as $item_id => $item) {
        $product = $item->get_product();
        $tax_class = $product->get_tax_class();
        $price = $item->get_total();
        $quantity = $item->get_quantity();

        // Format date
        $date = $order->get_date_created()->format('d/m/Y');

        // Build formatted order array
        $formatted_order[] = "$date,$item->get_order_item_id(),$item->get_product_id(),$product->get_name(),$price,$tax_class,$quantity";
    }

    return implode("\n", $formatted_order);
}

