function searchPlace(placeName) {
  var apiKey = 'YOUR_API_KEY';
  var url = `https://maps.googleapis.com/maps/api/geocode/json?address=${placeName}&key=${apiKey}`;

  var response = UrlFetchApp.fetch(url);
  var data = JSON.parse(response);

  if (data.results.length > 0) {
    var location = data.results[0].geometry.location;
    return {
      latitude: location.lat,
      longitude: location.lng
    };
  } else {
    return null;
  }
}

function storeLatLng(placeName, latitude, longitude) {
  // Assuming you have a spreadsheet with columns for place name, latitude, and longitude
  var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  sheet.getRange(sheet.getLastRow() + 1, 1).setValue(placeName);
  sheet.getRange(sheet.getLastRow() + 1, 2).setValue(latitude);
  sheet.getRange(sheet.getLastRow() + 1, 3).setValue(longitude);
}

function main() {
  var placeName = 'New York'; // Replace with the place name you want to search for
  var latitude = searchPlace(placeName).latitude;
  var longitude = searchPlace(placeName).longitude;

  if (latitude && longitude) {
