```go
package main

import (
	"fmt"
	"io/ioutil"
	"reflect"
	"strings"
)

func main() {
	file := "example.go" // Replace with the name of your Go source file
	structName := "MyStruct" // Replace with the name of the struct you want to convert

	data, err := ioutil.ReadFile(file)
	if err != nil {
		fmt.Println("Error reading file:", err)
		return
	}

	content := strings.TrimSpace(string(data))
	lines := strings.Split(content, "\n")

	for _, line := range lines {
		if strings.HasPrefix(line, "type") {
			parts := strings.SplitN(line, " ", 2)
			if len(parts) == 2 {
				structType := parts[1]
				if structType == structName {
					schema, err := generateSchema(reflect.TypeOf(structName))
					if err != nil {
						fmt.Println("Error generating schema:", err)
						return
					}
					err = ioutil.WriteFile("struct.avsc", []byte(schema), 0644)
					if err != nil {
						fmt.Println("Error writing schema file:", err)
						return
					}
					fmt.Printf("Avro schema generated for %s\n", structName)
					return
				}
			}
		}
	}

	fmt.Println("Struct not found in file.")
}

