Here's a simple React utility that removes widows from text. It uses the `string-width` library to measure the width of a string and wraps it in a component that adjusts the line breaks to prevent widows.

First, install the `string-width` library:

```bash
npm install string-width
```

Then, create a new file called `WidowRemover.js` and add the following code:

```javascript
import { useState } from 'react';
import { stringWidth } from 'string-width';

const WidowRemover = ({ children }) => {
  const [wrappedText, setWrappedText] = useState(children);

  const handleResize = () => {
    const containerWidth = document.getElementById('widow-remover').offsetWidth;
    const maxWidth = containerWidth - 10; // Adjust the margin as needed

    setWrappedText(wrappedText.replace(/\n/g, (match) => {
      const lines = match.split('\n');
      const adjustedLines = lines.map((line) => {
        const lineWidth = stringWidth(line);
        if (lineWidth > maxWidth) {
          return line.slice(0, maxWidth) + '\n';
        }
        return line;
      });
      return adjustedLines.join('\n');
    }));
  };

  return (
    <div id="widow-remover" style={{ overflow: 'hidden' }}>
      {wrappedText}
    </div>
  );
};

export default WidowRemover;
```

