#include <iostream>
#include <curl/curl.h>
#include <json/json.h>

using namespace std;

string getFacebookData(string url) {
    CURL *curl;
    CURLcode res;
    string readBuffer;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    return readBuffer;
}

int main() {
    string facebookUrl = "https://graph.facebook.com/v10.0/me/posts";
    string accessToken = "YOUR_ACCESS_TOKEN_HERE";

    string data = getFacebookData(facebookUrl + "?access_token=" + accessToken);
