    if (reader.parse(data, root)) {
        for (auto post : root["data"]) {
            cout << "Post ID: " << post["id"] << endl;
            cout << "Post Text: " << post["message"] << endl;
            cout << "Post Date: " << post["created_time"] << endl;
            cout << endl;
        }
    } else {
        cout << "Error parsing JSON" << endl;
    }

    return 0;
}
```

