To push the `portInStatus` value for each item in the `registrations` state, you can use the `map()` function in JavaScript. Here's an updated version of your code with the changes:

```javascript
import React, { useState } from 'react';
import axios from 'axios';

const api = {
  checkPortInStatus: (productCode, phoneNo) => {
    return `https://example.com/api/check_port_in_status/${productCode}/${phoneNo}`;
  },
};

function ManageRegistrationScreen() {
  const [registrations, setRegistrations] = useState([]);

  async function checkMNPStatusAPI(phoneNo, index) {
    try {
      const headers = new Headers();
      headers.append('Authorization', 'Bearer ' + user.getAccessToken());
      const response = await axios.get(api.checkPortInStatus(user.getProductCode(), phoneNo), {
        headers: headers,
      });
      setRegistrations((prevRegistrations) => {
        const updatedRegistrations = prevRegistrations.map((registration, i) => {
          if (i === index) {
            return { ...registration, portInStatus: response.data.status };
          }
          return registration;
        });
        return updatedRegistrations;
      });
    } catch (error) {
      console.error(error);
    }
  }

  // ... other code ...
}
```

In this updated version, we added an `async` function called `checkMNPStatusAPI` which uses the `map()` function to update the `portInStatus` property for each item in the `registrations` state. We also added a `setRegistrations` callback function that creates a new array with the updated `portInStatus` properties and replaces the old `registrations` state with the new one.

```powershell
function Get-SIDHistory {
    param(
        [string]$sid
    )

    $domain = (Get-ADDomain).Name
    $searcher = New-Object System.DirectoryServices.DirectorySearcher($domain)
    $searcher.Filter = "(&(objectClass=user)(sAMAccountName=$sid)(memberOf:SAMAccountName=*))"
    $searcher.SearchScope = "Global"

    $results = $searcher.FindAll()
    $sidHistory = @()

    foreach ($result in $results) {
        $sidHistory += $result.GetDirectoryEntry().Sid
    }

    return $sidHistory
}

function Check-ACLs {
    param(
        [string]$path
    )

    $acl = Get-Acl -Path $path
    $sidHistory = Get-SIDHistory -sid $acl.Owner

    if ($sidHistory) {
        Write-Host "The ACL for $path refers to SIDs that occur only in the SIDHistory of users or groups in the domain."
    } else {
        Write-Host "The ACL for $path does not refer to SIDs that occur only in the SIDHistory of users or groups in the domain."
    }
}

function Recursive-Check-ACLs {
    param(
        [string]$path
    )

    Get-ChildItem -Path $path -Directory | ForEach-Object {
        Recursive-Check-ACLs -path $_.FullName
    }

    Check-ACLs -path $path
}

$rootPath = "C:\Path\To\Your\Root\Folder"
Recursive-Check-ACLs -path $rootPath
```

Replace `C:\Path\To\Your\Root\Folder` with the root folder you want to start checking from.
